  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'LOGO-PACK');
  assert.equal(r2.value.lines[0].qty, 3);
});

test('addLine validates qty', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  assert.deepEqual(addLine(invoice, { sku: 'DES-HOUR', qty: 1.5 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'DES-HOUR', qty: 0 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'DES-HOUR', qty: -1 }), { ok: false, error: 'QTY_INVALID' });
});

test('addLine validates SKU exists', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  assert.deepEqual(addLine(invoice, { sku: 'UNKNOWN-SKU', qty: 1 }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine refuses to modify non-draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = { ...r.value, status: 'sent' };

  assert.deepEqual(addLine(invoice, { sku: 'DES-HOUR', qty: 1 }), { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
